// Monthly budget cap for Example home services company. Built 2026-10-21 from a live read of the account.
// Undo: in Campaigns, filter on the label "Paused by budget cap", enable those campaigns and remove the label.
// The script also does this itself on its first run under the cap (a new month or a raised cap).
const CONFIG = {
  LIVE: false,                          // false logs only. Set true after a clean Preview.
  MONTHLY_CAP: 14000,                    // USD, the account's whole spend this month
  SCOPE_LABEL: 'Budget cap: pause',      // the 6 non-brand campaigns; Brand never carries it
  PAUSED_LABEL: 'Paused by budget cap',
  MAX_CHANGES: 6,                       // the number of campaigns in scope
  EMAIL: 'ops@example.com',
};

function main() {
  const preview = AdsApp.getExecutionInfo().isPreview();
  const canChange = CONFIG.LIVE && !preview;
  const spend = monthToDateSpend();
  const lines = [];
  Logger.log('Month to date: ' + spend.toFixed(2) + ' of ' + CONFIG.MONTHLY_CAP + ' cap');
  let changes = 0;                      // pauses and re-enables both count against MAX_CHANGES
  if (spend >= CONFIG.MONTHLY_CAP) {
    if (canChange) ensureLabel(CONFIG.PAUSED_LABEL);
    forEachCampaign(campaignIds(CONFIG.SCOPE_LABEL, 'ENABLED'), function (c) {
      if (changes >= CONFIG.MAX_CHANGES) { Logger.log('Change cap reached, left running: ' + c.getName()); return; }
      lines.push((canChange ? 'PAUSED: ' : 'WOULD PAUSE: ') + c.getName() + ' (' + c.getId() + ')');
      if (canChange) { c.pause(); c.applyLabel(CONFIG.PAUSED_LABEL); }
      changes++;
    });
  } else {
    forEachCampaign(campaignIds(CONFIG.PAUSED_LABEL, 'PAUSED'), function (c) {
      if (changes >= CONFIG.MAX_CHANGES) { Logger.log('Change cap reached, left paused: ' + c.getName()); return; }
      lines.push((canChange ? 'ENABLED: ' : 'WOULD ENABLE: ') + c.getName() + ' (' + c.getId() + ')');
      if (canChange) { c.enable(); c.removeLabel(CONFIG.PAUSED_LABEL); }
      changes++;
    });
  }
  lines.forEach(function (l) { Logger.log(l); });
  notify('Budget cap: ' + lines.length + ' change(s)', lines, preview);
}

function monthToDateSpend() {
  const rows = AdsApp.search('SELECT metrics.cost_micros FROM customer WHERE segments.date DURING THIS_MONTH');
  let micros = 0;
  while (rows.hasNext()) micros += Number(rows.next().metrics.costMicros);
  return micros / 1e6;
}

function campaignIds(label, status) {
  const rows = AdsApp.search('SELECT campaign.id, campaign.name, campaign.status, label.name FROM campaign_label ' +
    "WHERE label.name = '" + label + "' AND campaign.status = '" + status + "'");
  const ids = [];
  while (rows.hasNext()) ids.push(Number(rows.next().campaign.id));
  return ids;
}

// AdsApp.campaigns() returns Search and Display only; Performance Max has its own selector.
function forEachCampaign(ids, fn) {
  if (!ids.length) return;
  [AdsApp.campaigns(), AdsApp.performanceMaxCampaigns()].forEach(function (selector) {
    const it = selector.withIds(ids).get();
    while (it.hasNext()) fn(it.next());
  });
}

function ensureLabel(name) {
  const it = AdsApp.labels().get();
  while (it.hasNext()) if (it.next().getName() === name) return;
  AdsApp.createLabel(name);
}

function notify(subject, lines, preview) {
  if (!CONFIG.EMAIL || !lines.length) return;
  MailApp.sendEmail(CONFIG.EMAIL, (preview ? '[PREVIEW] ' : '') + subject, lines.join('\n'));
}

// Broken final URL check for Example home services company. Built 2026-10-21 from a live read of the account.
// Alert only: this script changes nothing in the account, so there is nothing to undo.
const CONFIG = {
  MAX_URLS: 50,       // 11 distinct final URLs today, with room to grow
  EMAIL: 'ops@example.com',
};

function main() {
  const preview = AdsApp.getExecutionInfo().isPreview();
  const urls = {};
  collect("SELECT ad_group_ad.ad.id, ad_group_ad.ad.final_urls, ad_group.name, campaign.name FROM ad_group_ad " +
    "WHERE ad_group_ad.status = 'ENABLED' AND ad_group.status = 'ENABLED' AND campaign.status = 'ENABLED'",
    function (r) { return r.adGroupAd.ad.finalUrls; }, urls);
  // Performance Max sends traffic to asset group URLs, which the ad query does not return
  collect("SELECT asset_group.id, asset_group.final_urls, campaign.name FROM asset_group " +
    "WHERE asset_group.status = 'ENABLED' AND campaign.status = 'ENABLED'",
    function (r) { return r.assetGroup.finalUrls; }, urls);
  const all = Object.keys(urls);
  const broken = [];
  let checked = 0;
  for (const url of all.slice(0, CONFIG.MAX_URLS)) {
    if (AdsApp.getExecutionInfo().getRemainingTime() < 60) break;
    let code = 0;
    try { code = UrlFetchApp.fetch(url, {muteHttpExceptions: true, followRedirects: true}).getResponseCode(); } catch (e) { code = 0; }
    checked++;
    if (code === 0 || code >= 400) broken.push((code || 'no answer') + ': ' + url + ' (used by ' + Object.keys(urls[url]).join(', ') + ')');
  }
  Logger.log('Checked ' + checked + ' of ' + all.length + ' URLs, ' + broken.length + ' broken');
  broken.forEach(function (l) { Logger.log(l); });
  notify('Broken final URLs: ' + broken.length, broken, preview);
}

function collect(query, getUrls, urls) {
  const rows = AdsApp.search(query);
  while (rows.hasNext()) {
    const r = rows.next();
    (getUrls(r) || []).forEach(function (u) { (urls[u] = urls[u] || {})[r.campaign.name] = true; });
  }
}

function notify(subject, lines, preview) {
  if (!CONFIG.EMAIL || !lines.length) return;
  MailApp.sendEmail(CONFIG.EMAIL, (preview ? '[PREVIEW] ' : '') + subject, lines.join('\n'));
}

// Search terms to Google Sheets for Example home services company. Built 2026-10-21 from a live read of the account.
// Writes one tab only. Undo: delete the tab "Search terms (30 days)"; nothing in the account changes.
const CONFIG = {
  SHEET_URL: 'https://docs.google.com/spreadsheets/d/EXAMPLE-SHEET-ID/edit',
  TAB: 'Search terms (30 days)',
};

function main() {
  const tz = AdsApp.currentAccount().getTimeZone();
  const today = Utilities.formatDate(new Date(), tz, 'yyyy-MM-dd');
  const rows = AdsApp.search('SELECT search_term_view.search_term, search_term_view.status, campaign.name, ad_group.name, ' +
    'metrics.clicks, metrics.cost_micros, metrics.conversions FROM search_term_view ' +
    'WHERE segments.date DURING LAST_30_DAYS AND metrics.clicks > 0 ORDER BY metrics.cost_micros DESC');
  const out = [['Search term', 'Status', 'Campaign', 'Ad group', 'Clicks', 'Cost', 'Conversions', 'Run date']];
  while (rows.hasNext()) {
    const r = rows.next();
    out.push([r.searchTermView.searchTerm, r.searchTermView.status, r.campaign.name, r.adGroup.name,
      Number(r.metrics.clicks), Number(r.metrics.costMicros) / 1e6, Number(r.metrics.conversions), today]);
  }
  const ss = SpreadsheetApp.openByUrl(CONFIG.SHEET_URL);
  const sheet = ss.getSheetByName(CONFIG.TAB) || ss.insertSheet(CONFIG.TAB);
  sheet.clearContents();
  sheet.getRange(1, 1, out.length, out[0].length).setValues(out);
  Logger.log('Wrote ' + (out.length - 1) + ' search terms to ' + CONFIG.TAB);
}

// Spend jump alert for Example home services company. Built 2026-10-21 from a live read of the account.
// Alert only: this script changes nothing in the account, so there is nothing to undo.
const CONFIG = {
  JUMP_RATIO: 1.75,        // backtest: 0 alert(s) in the last 60 days at this ratio
  MIN_SPEND: 47,          // USD, 10% of the account's average daily spend
  EMAIL: 'ops@example.com',
};

function main() {
  const preview = AdsApp.getExecutionInfo().isPreview();
  const tz = AdsApp.currentAccount().getTimeZone();
  const DAY = 24 * 3600 * 1000, now = new Date();
  const fmt = function (t) { return Utilities.formatDate(new Date(t), tz, 'yyyy-MM-dd'); };
  const yesterday = fmt(now.getTime() - DAY);
  const start = fmt(now.getTime() - 29 * DAY);
  const rows = AdsApp.search('SELECT campaign.id, campaign.name, segments.date, metrics.cost_micros FROM campaign ' +
    "WHERE segments.date BETWEEN '" + start + "' AND '" + yesterday + "' AND metrics.cost_micros > 0");
  const cost = {};
  while (rows.hasNext()) {
    const r = rows.next();
    (cost[r.campaign.name] = cost[r.campaign.name] || {})[r.segments.date] = Number(r.metrics.costMicros) / 1e6;
  }
  const lines = [];
  Object.keys(cost).forEach(function (name) {
    const y = cost[name][yesterday] || 0;
    let sum = 0;
    for (let w = 1; w <= 4; w++) sum += cost[name][fmt(now.getTime() - (1 + 7 * w) * DAY)] || 0;
    const usual = sum / 4;
    if (y < CONFIG.MIN_SPEND) return;
    if (usual === 0) lines.push(name + ': ' + y.toFixed(2) + ' yesterday with no spend on the same weekday in 4 weeks (new spend)');
    else if (y / usual >= CONFIG.JUMP_RATIO) lines.push(name + ': ' + y.toFixed(2) + ' yesterday, usual ' + usual.toFixed(2) + ' (' + (y / usual).toFixed(2) + 'x)');
  });
  Logger.log(lines.length ? lines.join('\n') : 'No spend jumps on ' + yesterday);
  notify('Spend jump: ' + lines.length + ' campaign(s)', lines, preview);
}

function notify(subject, lines, preview) {
  if (!CONFIG.EMAIL || !lines.length) return;
  MailApp.sendEmail(CONFIG.EMAIL, (preview ? '[PREVIEW] ' : '') + subject, lines.join('\n'));
}

