// Your campaign click report, fixed. Reads only; changes nothing.
function main() {
  const tz = AdsApp.currentAccount().getTimeZone();
  const DAY = 24 * 3600 * 1000, now = new Date();
  const fmt = function (t) { return Utilities.formatDate(new Date(t), tz, 'yyyy-MM-dd'); };
  // DURING has no LAST_90_DAYS; compute the 90 complete days and use BETWEEN
  const rows = AdsApp.search('SELECT campaign.name, metrics.clicks, metrics.cost_micros FROM campaign ' +
    "WHERE segments.date BETWEEN '" + fmt(now.getTime() - 90 * DAY) + "' AND '" + fmt(now.getTime() - DAY) + "'");
  while (rows.hasNext()) {
    const r = rows.next();
    const cost = Number(r.metrics.costMicros) / 1e6;   // row fields are camelCase; cost_micros reads as undefined
    const clicks = Number(r.metrics.clicks);            // 64-bit numbers arrive as strings
    if (clicks > 90) Logger.log(r.campaign.name + ' ' + cost.toFixed(2));   // your clicks + 10 > 100, as a number
  }
}
